      "gradedSubmissions": [
        {
          "submissionId": "X",
          "demonstratedCore": true,
          "scores": [
            {
              "criterionId": "motion_models_1",
              "pointsAwarded": 8,
              "reason": "Alle sechs Einpunktbeiträge sind sichtbar: Längenkalibrierung, tatsächliche Bildzeiten, derselbe Bezugspunkt in beiden Koordinaten, datenbegründetes lineares x(t), datenbegründetes quadratisches f(t) und gemeinsame Zeit. Die Zeitausschaltung begründet die Parabel vollständig und verdient weitere 2 BE. Formeln und Koordinaten ergänzen die schematischen Graphen. Quellen: canonical-input.json:192, 1096."
            },
